<template><view class="page"><view class="title">提交投诉</view><view class="card"><view class="field-label">投诉原因</view><textarea class="input" v-model="reason" placeholder="请输入投诉原因"/><view class="field-label">证据图片（可选）</view><button class="btn secondary" @click="chooseImages">选择图片</button><view class="images"><view v-for="(path,index) in localImages" :key="path" class="image-wrap"><image :src="path" mode="aspectFill" @click="preview(path)"/><view class="remove-image" @click.stop="remove(index)">×</view></view></view><button class="btn danger" :loading="submitting" @click="submit">提交</button></view></view></template>
<script setup>
import { onLoad } from '@dcloudio/uni-app'; import { ref } from 'vue'; import { api } from '../../utils/request'; import { uploadCloudFile } from '../../utils/cloudStorage';
const orderId=ref(null),reason=ref(''),localImages=ref([]),submitting=ref(false);onLoad(q=>{orderId.value=q.orderId});
async function chooseImages(){try{const r=await uni.chooseImage({count:6-localImages.value.length,sizeType:['compressed']});for(const p of r.tempFilePaths)if(!localImages.value.includes(p))localImages.value.push(p)}catch(error){if(String(error?.errMsg||error?.message||'').toLowerCase().includes('cancel'))return;uni.showToast({title:'图片选择失败，请重试',icon:'none'})}} function remove(i){localImages.value.splice(i,1)} function preview(path){wx.previewImage({current:path,urls:localImages.value})}
async function submit(){if(submitting.value)return;if(!reason.value.trim()){uni.showToast({title:'请输入投诉原因',icon:'none'});return}submitting.value=true;const uploaded=[];try{for(const path of localImages.value)uploaded.push((await uploadCloudFile(path,'complaints')).fileID);await api.complaint({orderId:orderId.value,reason:reason.value,imageFileIds:uploaded});uni.navigateBack()}catch(error){if(uploaded.length)await wx.cloud.deleteFile({fileList:uploaded});const message=error?.code==='SYSTEM_NOT_INITIALIZED'?'系统数据尚未初始化，请联系管理员':(typeof error?.code==='string'&&error?.message?error.message:'投诉提交失败，请稍后重试');uni.showToast({title:message,icon:'none'})}finally{submitting.value=false}}
</script><style scoped>.field-label{margin:14rpx 0 10rpx;font-size:27rpx;font-weight:600}.images{display:flex;flex-wrap:wrap;gap:14rpx}.image-wrap{position:relative;width:150rpx;height:150rpx}.image-wrap image{width:100%;height:100%;border-radius:6px}.remove-image{position:absolute;right:-8rpx;top:-8rpx;width:38rpx;height:38rpx;line-height:35rpx;text-align:center;border-radius:50%;background:#dc2626;color:#fff;font-size:34rpx}</style>
